function r(n){const t=n.getTime();return{seconds:Math.floor(t/1e3),milliseconds:t,iso:n.toISOString(),local:n.toLocaleString("zh-CN"),utc:n.toUTCString()}}function s(n){const t=n.trim();if(!t||!/^-?\d+$/.test(t))return null;const e=Number(t),o=t.length<=10?e*1e3:e,i=new Date(o);return Number.isNaN(i.getTime())?null:r(i)}function u(n){const t=n.trim();if(!t)return null;const e=new Date(t);return Number.isNaN(e.getTime())?null:r(e)}function m(){return r(new Date)}export{u as a,s as f,m as n};
